var phase = 0;

async function setup() {
  _regW(0xE0028008, 0); // P0.25 = INPUT (DAC default)
}

async function loop() {
  var val = Math.round(512 + 511 * Math.sin(phase));
  _regW(0xE000C500, (val & 0x3FF) << 6);
  phase += 0.15;
  if (phase > 6.28) phase -= 6.28;
  await delay_ms(1);
}
